use std::io::{self, BufWriter, Write};
use std::process::ExitCode;

use wgpu::util::DeviceExt;

const MAX_DIM: usize = 512;
const MAX_STEPS: u32 = 1000;
const MAX_CELL: u32 = 1_000_000;
const WORKGROUP: u32 = 16;

const SHADER: &str = r#"
struct Params {
    width: u32,
    height: u32,
    _pad0: u32,
    _pad1: u32,
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(16, 16, 1)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    let w = params.width;
    let h = params.height;
    if (x >= w || y >= h) {
        return;
    }
    let row = y * w;
    let left = select(x - 1u, x, x == 0u);
    let right = select(x + 1u, x, x + 1u >= w);
    let up = select(y - 1u, y, y == 0u);
    let down = select(y + 1u, y, y + 1u >= h);

    let c = src[row + x];
    let total = 4u * c
        + src[row + left]
        + src[row + right]
        + src[up * w + x]
        + src[down * w + x];
    dst[row + x] = total / 8u;
}
"#;

struct Grid {
    width: usize,
    height: usize,
    steps: u32,
    cells: Vec<u32>,
}

fn parse_input(text: &str) -> Result<Grid, String> {
    let mut tokens = text.split_ascii_whitespace();
    let mut next_num = |what: &str| -> Result<u64, String> {
        let tok = tokens
            .next()
            .ok_or_else(|| format!("unexpected end of input while reading {what}"))?;
        tok.parse::<u64>()
            .map_err(|_| format!("invalid number {tok:?} for {what}"))
    };

    let width = next_num("width")?;
    let height = next_num("height")?;
    let steps = next_num("steps")?;
    if !(1..=MAX_DIM as u64).contains(&width) {
        return Err(format!("width {width} out of range 1..={MAX_DIM}"));
    }
    if !(1..=MAX_DIM as u64).contains(&height) {
        return Err(format!("height {height} out of range 1..={MAX_DIM}"));
    }
    if steps > u64::from(MAX_STEPS) {
        return Err(format!("steps {steps} out of range 0..={MAX_STEPS}"));
    }
    let (width, height) = (width as usize, height as usize);

    let mut cells = Vec::with_capacity(width * height);
    for i in 0..width * height {
        let v = next_num(&format!("cell at row {}, column {}", i / width, i % width))?;
        if v > u64::from(MAX_CELL) {
            return Err(format!("cell value {v} out of range 0..={MAX_CELL}"));
        }
        cells.push(v as u32);
    }
    if let Some(extra) = tokens.next() {
        return Err(format!("unexpected trailing data {extra:?}"));
    }

    Ok(Grid {
        width,
        height,
        steps: steps as u32,
        cells,
    })
}

async fn run_on_gpu(grid: &Grid) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::default();
    let adapter = instance
        .request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            force_fallback_adapter: false,
            compatible_surface: None,
        })
        .await
        .map_err(|e| format!("no GPU adapter available: {e}"))?;
    let (device, queue) = adapter
        .request_device(&wgpu::DeviceDescriptor::default())
        .await
        .map_err(|e| format!("failed to open GPU device: {e}"))?;

    let byte_len = (grid.cells.len() * std::mem::size_of::<u32>()) as wgpu::BufferAddress;
    let params: [u32; 4] = [grid.width as u32, grid.height as u32, 0, 0];

    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::cast_slice(&params),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let storage_usage =
        wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC | wgpu::BufferUsages::COPY_DST;
    let buf_a = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("grid a"),
        contents: bytemuck::cast_slice(&grid.cells),
        usage: storage_usage,
    });
    let buf_b = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("grid b"),
        size: byte_len,
        usage: storage_usage,
        mapped_at_creation: false,
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size: byte_len,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("heat stencil"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("heat pipeline"),
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });
    let layout = pipeline.get_bind_group_layout(0);
    let make_bind_group = |src: &wgpu::Buffer, dst: &wgpu::Buffer| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: None,
            layout: &layout,
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: params_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: src.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: dst.as_entire_binding(),
                },
            ],
        })
    };
    // Step i reads from one buffer and writes the other, so every cell of a
    // step sees only the values the previous step left.
    let a_to_b = make_bind_group(&buf_a, &buf_b);
    let b_to_a = make_bind_group(&buf_b, &buf_a);

    let groups_x = (grid.width as u32).div_ceil(WORKGROUP);
    let groups_y = (grid.height as u32).div_ceil(WORKGROUP);

    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
        label: Some("heat steps"),
    });
    for step in 0..grid.steps {
        // A separate pass per step guarantees the writes of one step are
        // visible to the reads of the next.
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
            label: None,
            timestamp_writes: None,
        });
        pass.set_pipeline(&pipeline);
        let bind_group = if step % 2 == 0 { &a_to_b } else { &b_to_a };
        pass.set_bind_group(0, bind_group, &[]);
        pass.dispatch_workgroups(groups_x, groups_y, 1);
    }
    let result = if grid.steps % 2 == 0 { &buf_a } else { &buf_b };
    encoder.copy_buffer_to_buffer(result, 0, &readback, 0, byte_len);
    queue.submit(Some(encoder.finish()));

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |res| {
        let _ = tx.send(res);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    rx.recv()
        .map_err(|_| "GPU readback never completed".to_string())?
        .map_err(|e| format!("failed to map readback buffer: {e}"))?;

    let out = {
        let data = slice.get_mapped_range();
        bytemuck::cast_slice::<u8, u32>(&data).to_vec()
    };
    readback.unmap();
    Ok(out)
}

fn write_output(grid: &Grid, cells: &[u32]) -> io::Result<()> {
    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());
    let mut sum: u64 = 0;
    for row in cells.chunks(grid.width) {
        for (i, v) in row.iter().enumerate() {
            if i > 0 {
                out.write_all(b" ")?;
            }
            write!(out, "{v}")?;
            sum += u64::from(*v);
        }
        out.write_all(b"\n")?;
    }
    writeln!(out, "SUM {sum}")?;
    out.flush()
}

fn main() -> ExitCode {
    let Some(path) = std::env::args_os().nth(1) else {
        eprintln!("usage: gpu_heat <input-file>");
        return ExitCode::from(2);
    };
    let text = match std::fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("cannot read {}: {e}", path.to_string_lossy());
            return ExitCode::FAILURE;
        }
    };
    let grid = match parse_input(&text) {
        Ok(g) => g,
        Err(e) => {
            eprintln!("invalid input: {e}");
            return ExitCode::FAILURE;
        }
    };
    let cells = match pollster::block_on(run_on_gpu(&grid)) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("GPU error: {e}");
            return ExitCode::FAILURE;
        }
    };
    if let Err(e) = write_output(&grid, &cells) {
        eprintln!("failed to write output: {e}");
        return ExitCode::FAILURE;
    }
    ExitCode::SUCCESS
}

