        mapped_at_creation: false,
    });

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("heat stencil"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("heat pipeline"),
        layout: None,
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });
    let layout = pipeline.get_bind_group_layout(0);
    let make_bind_group = |src: &wgpu::Buffer, dst: &wgpu::Buffer| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: None,
            layout: &layout,
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: params_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: src.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: dst.as_entire_binding(),
                },
            ],
        })
    };
    // Step i reads from one buffer and writes the other, so every cell of a
    // step sees only the values the previous step left.
    let a_to_b = make_bind_group(&buf_a, &buf_b);
    let b_to_a = make_bind_group(&buf_b, &buf_a);

    let groups_x = (grid.width as u32).div_ceil(WORKGROUP);
    let groups_y = (grid.height as u32).div_ceil(WORKGROUP);

    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
        label: Some("heat steps"),
    });
    for step in 0..grid.steps {
        // A separate pass per step guarantees the writes of one step are
        // visible to the reads of the next.
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
            label: None,
            timestamp_writes: None,
        });
        pass.set_pipeline(&pipeline);
        let bind_group = if step % 2 == 0 { &a_to_b } else { &b_to_a };
        pass.set_bind_group(0, bind_group, &[]);
        pass.dispatch_workgroups(groups_x, groups_y, 1);
    }
    let result = if grid.steps % 2 == 0 { &buf_a } else { &buf_b };
    encoder.copy_buffer_to_buffer(result, 0, &readback, 0, byte_len);
    queue.submit(Some(encoder.finish()));

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |res| {
        let _ = tx.send(res);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    rx.recv()
        .map_err(|_| "GPU readback never completed".to_string())?
        .map_err(|e| format!("failed to map readback buffer: {e}"))?;

    let out = {
        let data = slice.get_mapped_range();
        bytemuck::cast_slice::<u8, u32>(&data).to_vec()
    };
    readback.unmap();
    Ok(out)
}

fn write_output(grid: &Grid, cells: &[u32]) -> io::Result<()> {
    let stdout = io::stdout();
    let mut out = BufWriter::new(stdout.lock());
    let mut sum: u64 = 0;
    for row in cells.chunks(grid.width) {
        for (i, v) in row.iter().enumerate() {
            if i > 0 {
                out.write_all(b" ")?;
            }
            write!(out, "{v}")?;
            sum += u64::from(*v);
        }
        out.write_all(b"\n")?;
    }
    writeln!(out, "SUM {sum}")?;
    out.flush()
}

fn main() -> ExitCode {
    let Some(path) = std::env::args_os().nth(1) else {
        eprintln!("usage: gpu_heat <input-file>");
        return ExitCode::from(2);
    };
    let text = match std::fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("cannot read {}: {e}", path.to_string_lossy());
            return ExitCode::FAILURE;
        }
    };
    let grid = match parse_input(&text) {
        Ok(g) => g,
        Err(e) => {
            eprintln!("invalid input: {e}");
            return ExitCode::FAILURE;
        }
    };
    let cells = match pollster::block_on(run_on_gpu(&grid)) {
        Ok(c) => c,
        Err(e) => {
            eprintln!("GPU error: {e}");
            return ExitCode::FAILURE;
        }
    };
    if let Err(e) = write_output(&grid, &cells) {
        eprintln!("failed to write output: {e}");
        return ExitCode::FAILURE;
    }
    ExitCode::SUCCESS
}
